"""Run exact B19 artifact adaptation then isolate controlled deferred network cases.
Only QA test code changes; product bytes/asserted provider behavior do not.
Usage: b19_final_qa_adapt_v3.py QA_DIR
"""
from pathlib import Path
import hashlib,json,sys
base=Path(__file__).with_name('b19_final_qa_adapt_v2.py')
code=base.read_text()
exec(compile(code,str(base),'exec'),{'__name__':'__main__','__file__':str(base),'sys':sys})
root=Path(sys.argv[1]).resolve();p=root/'b12_contract.test.mjs';s=p.read_text()
old="""const asyncNetwork=observed=>async(url,init)=>{\n const u=String(url);observed.push({url:u,method:init?.method||'GET',authorization:init?.headers?.Authorization||null,body:init?.body?JSON.parse(init.body):null});\n if(u==='https://searchapi.api.cloud.yandex.net/v2/web/searchAsync')return new Response(JSON.stringify({id:'contract-op',done:false}),{status:200,headers:{'content-type':'application/json'}});\n if(u==='https://operation.api.cloud.yandex.net/operations/contract-op')return new Response(JSON.stringify({id:'contract-op',done:true,response:{rawData:raw(1)}}),{status:200,headers:{'content-type':'application/json'}});\n throw new Error('UNEXPECTED_ASYNC_URL '+u);\n};\nfor(const action of ['submit','submitN'])test('network-enabled '+action+' executes exactly one controlled searchAsync request with stored Search credential',async()=>{\n const observed=[],h=await loadWorker(full,{network:asyncNetwork(observed)});h.seedBoundChat();const j='submit-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));assert.equal(r.request_executed,false);await finish(h);r=await send(h,{action,jobId:j,...(action==='submitN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://searchapi.api.cloud.yandex.net/v2/web/searchAsync');assert.equal(observed[0].method,'POST');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal(observed[0].body.folderId,'folder');assert.equal((await h.context.YMBSearchAsyncStore.getSummary(j,KEY)).counts.WAITING,1);await finish(h);\n});\nfor(const action of ['collect','collectN','collectReady'])test('network-enabled '+action+' executes exactly one controlled Operation GET and locally normalizes result',async()=>{\n const observed=[],h=await loadWorker(full,{network:asyncNetwork(observed)});h.seedBoundChat();const j='collect-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));await finish(h);const s=h.context.YMBSearchAsyncStore,c=await s.claim({jobId:j,owner:KEY,workerId:'seed',attemptId:'seed',kind:'submit',now:1});assert.equal(c.allowed,true);await s.finishSubmit({jobId:j,owner:KEY,index:0,attemptId:'seed',outcome:'accepted',operationId:'contract-op',nextPollAt:0,now:2});r=await send(h,{action,jobId:j,...(action==='collectN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://operation.api.cloud.yandex.net/operations/contract-op');assert.equal(observed[0].method,'GET');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal((await s.getSummary(j,KEY)).counts.SUCCEEDED,1);assert.equal((await s.readResult(j,KEY,0)).normalized.results[0].url,'https://example.test/0');await finish(h);\n});"""
new="""let b19Clock=Date.now()+1000000;\nconst nextB19Clock=()=>({now:(b19Clock+=1000)});\nconst asyncNetwork=(observed,operationId)=>async(url,init)=>{\n const u=String(url);observed.push({url:u,method:init?.method||'GET',authorization:init?.headers?.Authorization||null,body:init?.body?JSON.parse(init.body):null});\n if(u==='https://searchapi.api.cloud.yandex.net/v2/web/searchAsync')return new Response(JSON.stringify({id:operationId,done:false}),{status:200,headers:{'content-type':'application/json'}});\n if(u==='https://operation.api.cloud.yandex.net/operations/'+operationId)return new Response(JSON.stringify({id:operationId,done:true,response:{rawData:raw(1)}}),{status:200,headers:{'content-type':'application/json'}});\n throw new Error('UNEXPECTED_ASYNC_URL '+u);\n};\nfor(const action of ['submit','submitN'])test('network-enabled '+action+' executes exactly one controlled searchAsync request with stored Search credential',async()=>{\n const observed=[],operationId='submit-op-'+crypto.randomUUID(),h=await loadWorker(full,{network:asyncNetwork(observed,operationId),clock:nextB19Clock()});h.seedBoundChat();const j='submit-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));assert.equal(r.request_executed,false);await finish(h);r=await send(h,{action,jobId:j,...(action==='submitN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://searchapi.api.cloud.yandex.net/v2/web/searchAsync');assert.equal(observed[0].method,'POST');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal(observed[0].body.folderId,'folder');assert.equal((await h.context.YMBSearchAsyncStore.getSummary(j,KEY)).counts.WAITING,1);await finish(h);\n});\nfor(const action of ['collect','collectN','collectReady'])test('network-enabled '+action+' executes exactly one controlled Operation GET and locally normalizes result',async()=>{\n const observed=[],operationId='collect-op-'+crypto.randomUUID(),h=await loadWorker(full,{network:asyncNetwork(observed,operationId),clock:nextB19Clock()});h.seedBoundChat();const j='collect-'+action+'-'+crypto.randomUUID();let r=await send(h,start({jobId:j}));await finish(h);const s=h.context.YMBSearchAsyncStore,c=await s.claim({jobId:j,owner:KEY,workerId:'seed',attemptId:'seed',kind:'submit',now:1});assert.equal(c.allowed,true);await s.finishSubmit({jobId:j,owner:KEY,index:0,attemptId:'seed',outcome:'accepted',operationId,nextPollAt:0,now:2});r=await send(h,{action,jobId:j,...(action==='collectN'?{count:1}:{})});assert.equal(r.request_executed,true,r.report_text);assert.equal(observed.length,1);assert.equal(observed[0].url,'https://operation.api.cloud.yandex.net/operations/'+operationId);assert.equal(observed[0].method,'GET');assert.equal(observed[0].authorization,'Api-Key TEST_SEARCH_NOT_REAL');assert.equal((await s.getSummary(j,KEY)).counts.SUCCEEDED,1);assert.equal((await s.readResult(j,KEY,0)).normalized.results[0].url,'https://example.test/0');await finish(h);\n});"""
if s.count(old)!=1:raise ValueError('Expected adapted deferred network test block not found')
s=s.replace(old,new);p.write_text(s)
rp=root/'B19_QA_ADAPTATION.json';r=json.loads(rp.read_text());r['schema_version']=3;r['artifact_isolation_fix']={'b12_after_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'reason':'unique operation ids and monotonic test clock for shared deterministic IDB/rate fixture'};rp.write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps(r,indent=2))
